function TeacherStudents({ data, persist, onImpersonateStudent, canViewPasswords, isAdmin }) {
  const [form, setForm] = useState({ name: "", class: (data.classes && data.classes[0]) || "", number: "", studentCode: "", username: "", password: "1234" });
  const [showForm, setShowForm] = useState(false);
  const [viewingId, setViewingId] = useState(null);
  const [classFilter, setClassFilter] = useState("all");
  const [visiblePw, setVisiblePw] = useState({});
  const [selectedIds, setSelectedIds] = useState([]);
  const [bulkTargetClass, setBulkTargetClass] = useState((data.classes && data.classes[0]) || "");
  const [bulkMoveMsg, setBulkMoveMsg] = useState("");
  const [confirmDeleteId, setConfirmDeleteId] = useState(null);

  async function addStudent() {
    if (!form.name || !form.username) return;
    const id = genId("s");
    try {
      const nextData = await sbConditionalSave((latest) => {
        const nextStudents = [...latest.students, { id, name: form.name, class: form.class, number: Number(form.number) || latest.students.length + 1, studentCode: form.studentCode }];
        const nextUsers = [...latest.users, { username: form.username, password: form.password || "1234", role: "student", studentId: id }];
        return { ...latest, students: nextStudents, users: nextUsers };
      });
      persist(nextData);
    } catch (e) {
      alert("บันทึกไม่สำเร็จ กรุณาลองใหม่อีกครั้ง");
      return;
    }
    setForm({ name: "", class: (data.classes && data.classes[0]) || "", number: "", studentCode: "", username: "", password: "1234" });
    setShowForm(false);
  }

  function removeStudent(id) {
    persist({
      ...data,
      students: data.students.filter((s) => s.id !== id),
      users: data.users.filter((u) => u.studentId !== id),
      grades: data.grades.filter((g) => g.studentId !== id),
      attendance: data.attendance.filter((a) => a.studentId !== id),
    });
    setConfirmDeleteId(null);
  }

  function handleExportCSV() {
    const list = classFilter === "all" ? data.students : data.students.filter((s) => s.class === classFilter);
    const rows = [
      ["เลขที่", "รหัสนักเรียน", "ชื่อ-นามสกุล", "ชั้นเรียน", "Username", "Password"],
      ...list.map((s) => {
        const u = data.users.find((user) => user.studentId === s.id);
        return [s.number, s.studentCode || "", s.name, s.class, u ? u.username : "", u ? u.password : ""];
      })
    ];
    exportToCSV(`students_${classFilter}_${new Date().toISOString().slice(0, 10)}.csv`, rows);
  }

  return (
    <div>
      <div className="sp-page-head">
        <h1>จัดการนักเรียน</h1>
        <div style={{ display: "flex", gap: "8px" }}>
          <button className="sp-btn-primary" type="button" onClick={handleExportCSV}><Download size={16} /> ส่งออก CSV</button>
          <button className="sp-btn-primary" onClick={() => setShowForm((s) => !s)}><Plus size={16} /> เพิ่มนักเรียน</button>
        </div>
      </div>

      {showForm && (
        <div className="sp-card">
          <div className="sp-form-grid">
            <div><label className="sp-label">ชื่อ-นามสกุล</label><input className="sp-input" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></div>
            <div>
              <label className="sp-label">ชั้น</label>
              <select className="sp-select" value={form.class} onChange={(e) => setForm({ ...form, class: e.target.value })}>
                {(data.classes || []).map((c) => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>
            <div><label className="sp-label">เลขที่</label><input className="sp-input" type="number" value={form.number} onChange={(e) => setForm({ ...form, number: e.target.value })} /></div>
            <div><label className="sp-label">รหัสนักเรียน</label><input className="sp-input" value={form.studentCode} onChange={(e) => setForm({ ...form, studentCode: e.target.value })} placeholder="เช่น 6621230007" /></div>
            <div><label className="sp-label">ชื่อผู้ใช้ (Login)</label><input className="sp-input" value={form.username} onChange={(e) => setForm({ ...form, username: e.target.value })} /></div>
            <div><label className="sp-label">รหัสผ่านเริ่มต้น</label><input className="sp-input" value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} /></div>
            <button className="sp-btn-primary" type="button" onClick={addStudent}>บันทึก</button>
          </div>
        </div>
      )}

      <div className="sp-card">
        <label className="sp-label">กรองตามชั้นเรียน</label>
        <select className="sp-select" value={classFilter} onChange={(e) => setClassFilter(e.target.value)}>
          <option value="all">ทุกชั้นเรียน</option>
          {(data.classes || []).map((c) => <option key={c} value={c}>{c}</option>)}
        </select>
      </div>

      <div className="sp-card">
        <table className="sp-table">
          <thead>
            <tr>
              <th>เลขที่</th>
              <th>ชื่อ</th>
              <th>รหัสนักเรียน</th>
              <th>ชั้น</th>
              <th>Username</th>
              {canViewPasswords && <th>รหัสผ่าน</th>}
              <th></th>
            </tr>
          </thead>
          <tbody>
            {(classFilter === "all" ? data.students : data.students.filter((s) => s.class === classFilter)).map((s) => {
              const u = data.users.find((u) => u.studentId === s.id);
              return (
                <tr key={s.id}>
                  <td>{s.number}</td>
                  <td>{s.name}</td>
                  <td>{s.studentCode || "-"}</td>
                  <td>{s.class}</td>
                  <td>{u ? u.username : "-"}</td>
                  {canViewPasswords && (
                    <td>
                      {u ? (
                        <button className="sp-pw-reveal" type="button" onClick={() => setVisiblePw((v) => ({ ...v, [s.id]: !v[s.id] }))}>
                          {visiblePw[s.id] ? u.password : "••••••••"}
                          {visiblePw[s.id] ? <EyeOff size={13} /> : <Eye size={13} />}
                        </button>
                      ) : "-"}
                    </td>
                  )}
                  <td style={{ display: "flex", gap: "4px" }}>
                    <button className="sp-icon-btn" onClick={() => setViewingId(s.id)} title="ดูโปรไฟล์"><User size={16} /></button>
                    <button className="sp-icon-btn" onClick={() => removeStudent(s.id)} title="ลบนักเรียน"><Trash2 size={16} /></button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function TeacherGradeManagement({ data, persist, session }) {
  const [yearId, setYearId] = useState(data.academicYears.find((y) => y.isCurrent)?.id || data.academicYears[0]?.id);
  const [termId, setTermId] = useState(data.terms.find((t) => t.isCurrent)?.id || data.terms[0]?.id);
  const [selectedAssignment, setSelectedAssignment] = useState(null);
  const [scoreInputs, setScoreInputs] = useState({});

  const myAssignments = data.subjectTeacherAssignments.filter((a) => a.teacherUsername === session.username && a.termId === termId);
  const activeAssignment = selectedAssignment ? myAssignments.find((a) => a.id === selectedAssignment) : myAssignments[0];
  const term = data.terms.find((t) => t.id === termId);
  const isLocked = term?.status === "closed";
  const classStudents = activeAssignment ? data.students.filter((s) => s.class === activeAssignment.class) : [];

  function getGrade(studentId) {
    return data.grades.find((g) => g.studentId === studentId && g.subject === activeAssignment?.subject && g.termId === termId);
  }

  function saveScores() {
    let next = { ...data };
    Object.entries(scoreInputs).forEach(([key, val]) => {
      const [studentId] = key.split("_");
      if (!key.startsWith(studentId) || val === "" || val === undefined) return;
      const existing = next.grades.find((g) => g.studentId === studentId && g.subject === activeAssignment.subject && g.termId === termId);
      const score = Number(val);
      if (isNaN(score)) return;
      if (existing) {
        next = { ...next, grades: next.grades.map((g) => (g === existing ? { ...g, score } : g)) };
      } else {
        next = { ...next, grades: [...next.grades, { id: genId("g"), studentId, subject: activeAssignment.subject, term: `เทอม ${term.termNumber}/${data.academicYears.find((y) => y.id === yearId)?.label}`, termId, score }] };
      }
    });
    persist(next);
    setScoreInputs({});
    alert("บันทึกคะแนนเรียบร้อยแล้ว");
  }

  function handleExportGradeCSV() {
    if (!activeAssignment) return;
    const rows = [
      ["รหัสนักเรียน", "ชื่อ-นามสกุล", "วิชา", "คะแนน", "เกรด"],
      ...classStudents.map((s) => {
        const g = getGrade(s.id);
        const score = g ? g.score : 0;
        return [s.studentCode || "", s.name, activeAssignment.subject, score, scoreToPoint(score)];
      })
    ];
    exportToCSV(`grades_${activeAssignment.subject}_${activeAssignment.class}.csv`, rows);
  }

  return (
    <div>
      <div className="sp-page-head">
        <h1>จัดการเกรด</h1>
        {activeAssignment && (
          <button className="sp-btn-primary" type="button" onClick={handleExportGradeCSV}><Download size={16} /> ส่งออกคะแนน (CSV)</button>
        )}
      </div>

      <div className="sp-card">
        <div className="sp-gm-header">
          <select className="sp-select" value={yearId} onChange={(e) => setYearId(e.target.value)}>
            {data.academicYears.map((y) => <option key={y.id} value={y.id}>ปีการศึกษา {y.label}</option>)}
          </select>
          <select className="sp-select" value={termId} onChange={(e) => { setTermId(e.target.value); setSelectedAssignment(null); }}>
            {data.terms.filter((t) => t.academicYearId === yearId).map((t) => <option key={t.id} value={t.id}>เทอม {t.termNumber}</option>)}
          </select>
          {myAssignments.length > 0 && (
            <select className="sp-select" value={activeAssignment?.id || ""} onChange={(e) => setSelectedAssignment(e.target.value)}>
              {myAssignments.map((a) => <option key={a.id} value={a.id}>{a.subject} · {a.class}</option>)}
            </select>
          )}
          <span className={"sp-lock-badge" + (isLocked ? " locked" : " open")}>{isLocked ? "ปิดเทอม — ล็อกการแก้ไข" : "เปิดให้กรอก"}</span>
        </div>
      </div>

      <div className="sp-card">
        {myAssignments.length === 0 ? (
          <div className="sp-empty">คุณยังไม่ได้รับมอบหมายให้สอนวิชาใดในเทอมนี้</div>
        ) : (
          <div>
            <table className="sp-table">
              <thead><tr><th>นักเรียน</th><th>คะแนน (เต็ม 100)</th><th>เกรด</th></tr></thead>
              <tbody>
                {classStudents.map((s) => {
                  const g = getGrade(s.id);
                  const key = `${s.id}_${activeAssignment?.subject}_${termId}`;
                  const val = scoreInputs[key] !== undefined ? scoreInputs[key] : (g ? g.score : "");
                  return (
                    <tr key={s.id}>
                      <td>{s.name}</td>
                      <td><input className="sp-input sp-grade-input" type="number" min="0" max="100" disabled={isLocked} value={val} onChange={(e) => setScoreInputs((prev) => ({ ...prev, [key]: e.target.value }))} /></td>
                      <td>{g ? scoreToPoint(g.score).toFixed(1) : "-"}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
            {!isLocked && (
              <button className="sp-btn-primary" style={{ marginTop: "14px" }} type="button" onClick={saveScores}>บันทึกคะแนน</button>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

