export default function App() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [session, setSession] = useState(null);
  const [view, setView] = useState("students");
  const [theme, setThemeState] = useState("light");

  useEffect(() => {
    load();
  }, []);

  async function load() {
    try {
      const remote = await sbGetState();
      setData(remote ? { ...SEED, ...remote } : SEED);
    } catch (e) {
      setData(SEED);
    } finally {
      setLoading(false);
    }
  }

  async function persist(next) {
    setData(next);
    await sbSaveState(next);
  }

  if (loading || !data) return <div style={{ padding: 40 }}>กำลังโหลดข้อมูล...</div>;

  return (
    <>
      <GlobalStyle />
      <div className={`sp-app ${theme}`}>
        <aside className="sp-sidebar-desktop">
          <button className="sp-sidebar-brand" onClick={() => setView("students")}>
            <img src={LOGO} alt="logo" className="sp-seal-sm" />
            <span className="sp-brand-name-sm">B.T.AD</span>
          </button>
          <nav className="sp-nav">
            <button className={`sp-nav-item ${view === "students" ? "active" : ""}`} onClick={() => setView("students")}>
              <Users size={18} /> <span>จัดการนักเรียน</span>
            </button>
            <button className={`sp-nav-item ${view === "grades" ? "active" : ""}`} onClick={() => setView("grades")}>
              <BookOpen size={18} /> <span>จัดการเกรด</span>
            </button>
          </nav>
        </aside>
        <main className="sp-main">
          {view === "students" && (
            <TeacherStudents data={data} persist={persist} canViewPasswords={true} isAdmin={true} />
          )}
          {view === "grades" && (
            <TeacherGradeManagement data={data} persist={persist} session={{ username: "kruping" }} />
          )}
        </main>
      </div>
    </>
  );
}
